#!/usr/bin/env node
// SPDX-License-Identifier: MIT
// Generated by metaharness — the `cognitum-ops-agent` CLI entry point.
//
// This is plain ESM JavaScript on purpose: it runs as-is via `npx cognitum-ops-agent`
// with NO build step. `npm run build` (tsc) is only needed if you extend the
// TypeScript in src/. The published package ships this file directly (see the
// "bin" + "files" fields in package.json), so `npx cognitum-ops-agent` works the moment
// `npm install` has resolved @metaharness/kernel + @metaharness/host-claude-code.

import { loadKernel } from '@metaharness/kernel';
import adapter from '@metaharness/host-claude-code';
import { kpiSnapshot, promotionBrief, formatBrief } from './lib/ops.js';
import { serve, toolManifest } from './lib/mcp.js';

const HARNESS_NAME = 'cognitum-ops-agent';

/** `cognitum-ops-agent init` — boot the kernel + host adapter and report status. */
async function init() {
  const kernel = await loadKernel();
  const info = kernel.kernelInfo();
  console.log(`${HARNESS_NAME} — kernel ${info.version} (${kernel.backend})`);
  console.log(`Host adapter: ${adapter.name}`);
  console.log(`Run \`${HARNESS_NAME} doctor\` to verify the install.`);
  return 0;
}

/** `cognitum-ops-agent doctor` — verify the install end-to-end (kernel + host resolve). */
async function doctor() {
  const kernel = await loadKernel();
  const info = kernel.kernelInfo();
  const checks = [
    ['kernel loads', !!kernel],
    ['kernel reports a version', typeof info.version === 'string' && info.version.length > 0],
    ['kernel backend is native|wasm|js', ['native', 'wasm', 'js'].includes(kernel.backend)],
    ['host adapter has a name', typeof adapter?.name === 'string' && adapter.name.length > 0],
  ];
  let ok = true;
  for (const [label, pass] of checks) {
    console.log(`${pass ? 'PASS' : 'FAIL'} ${label}`);
    if (!pass) ok = false;
  }
  console.log(
    ok
      ? `\n${HARNESS_NAME}: all checks passed (kernel ${info.version}, ${kernel.backend} backend, host ${adapter.name})`
      : `\n${HARNESS_NAME}: doctor found problems`,
  );
  return ok ? 0 : 1;
}

/**
 * Dispatch one CLI invocation. Exported (not just run on import) so a test can
 * drive it without spawning a subprocess. Returns the intended exit code.
 */
/** `cognitum-ops-agent metrics <file.json>` — analyst tool: rows → findings. */
async function metrics(args) {
  const rows = await readJsonArg(args[0]);
  const out = kpiSnapshot(rows);
  console.log(JSON.stringify(out, null, 2));
  return 0;
}

/** `cognitum-ops-agent promo <file.json>` — promoter tool: bet → measurable brief. */
async function promo(args) {
  const input = await readJsonArg(args[0]);
  const brief = promotionBrief(input);
  console.log(args.includes('--json') ? JSON.stringify(brief, null, 2) : formatBrief(brief));
  return 0;
}

/** `cognitum-ops-agent tools` — print the MCP tool schemas as JSON. */
async function tools() {
  console.log(JSON.stringify(toolManifest(), null, 2));
  return 0;
}

/** Read a JSON argument from a file path, or from stdin when arg is "-" / absent. */
async function readJsonArg(pathArg) {
  const { readFile } = await import('node:fs/promises');
  if (pathArg && pathArg !== '-') return JSON.parse(await readFile(pathArg, 'utf8'));
  const chunks = [];
  for await (const c of process.stdin) chunks.push(c);
  return JSON.parse(Buffer.concat(chunks).toString('utf8'));
}

export async function run(argv) {
  const cmd = argv[0] ?? 'init';
  switch (cmd) {
    case 'init':
      return init();
    case 'doctor':
      return doctor();
    case 'metrics':
      return metrics(argv.slice(1));
    case 'promo':
      return promo(argv.slice(1));
    case 'tools':
      return tools();
    case 'mcp':
      // `mcp start` (or bare `mcp`) runs the stdio JSON-RPC server; it blocks.
      serve();
      return new Promise(() => {});
    case '--version':
    case '-v': {
      const kernel = await loadKernel();
      console.log(kernel.version());
      return 0;
    }
    case '--help':
    case '-h':
      console.log(`Usage: ${HARNESS_NAME} <command>\n\n  init       boot the kernel + host adapter (default)\n  doctor     verify the install end-to-end\n  metrics <f.json>   analyst tool: KPI rows -> findings\n  promo <f.json>     promoter tool: bet -> measurable promotion brief (--json for raw)\n  tools      print the MCP tool schemas as JSON\n  mcp start  run the MCP stdio server (JSON-RPC over stdio)\n  --version  print the kernel version`);
      return 0;
    default:
      console.error(`Unknown command: ${cmd}. Try \`${HARNESS_NAME} --help\`.`);
      return 2;
  }
}

// CLI guard: execute only when invoked directly (not when imported by a test).
// npm's bin shims pass a NON-normalized argv[1] (e.g. ".../.bin/../<pkg>/bin/cli.js"
// on Windows) and may differ in case, so realpath BOTH sides before comparing —
// a naive string === misses the npx/shim path and the CLI silently no-ops.
import { fileURLToPath } from 'node:url';
import { realpathSync } from 'node:fs';
import { argv } from 'node:process';
const invokedDirectly = (() => {
  if (!argv[1]) return false;
  try {
    const a = realpathSync(argv[1]);
    const b = realpathSync(fileURLToPath(import.meta.url));
    return process.platform === 'win32' ? a.toLowerCase() === b.toLowerCase() : a === b;
  } catch {
    return false;
  }
})();
if (invokedDirectly) {
  run(argv.slice(2))
    .then((code) => process.exit(code))
    .catch((err) => {
      console.error(err);
      process.exit(1);
    });
}
